    word_count = {}

    # Count the occurrences of each word in the dictionary
    for word in dictionary:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Find the maximum count of any word
    max_count = max(word_count.values())

    # Filter the dictionary to include only words with the maximum count
    common_words = {word: count for word, count in word_count.items() if count == max_count}

    return common_words
