def next_smallest_palindrome(n):
    # Convert the number to a string to easily manipulate digits
    str_n = str(n)
    # Check if the number is already a palindrome
    if str_n == str_n[::-1]:
        return n  # Return the number as it is, which is already a palindrome
    # If not, convert the number to a list of its digits
    digits = [int(digit) for digit in str_n]
    # Find the index where the first digit is greater than the second
    for i in range(len(digits)):
        if digits[i] > digits[i + 1]:
            # Swap the digits at the found index and reverse the remaining digits
            digits[i], digits[i + 1] = digits[i + 1], digits[i]
            # Convert the list back to a string and reverse it again
            return int(''.join(str(x) for x in digits[::-1]))
    # If no such pair is found, return the next palindrome by incrementing the last digit
    digits[-1] += 1
    return int(''.join(str(x) for x in digits))
```

