def max_path_sum(triangle, m, n):
    # Initialize the first row of the triangle with the elements of the first row of the original triangle
    for i in range(1, m):
        triangle[i][0] += triangle[i-1][0]

    # Fill the triangle from the second row to the last row
    for i in range(1, m):
        for j in range(1, n):
            triangle[i][j] = max(triangle[i-1][j], triangle[i-1][j-1]) + triangle[i][j]

    # The maximum path sum is the value in the bottom-right corner of the triangle
    return triangle[m-1][n-1]
```

