import heapq

def heap_queue_smallest(numbers, k):
    # Use nlargest from heapq to get the k smallest elements
    return heapq.nlargest(k, numbers)
```

```python
def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a
```

```python
def permutation_coefficient(n, k):
    # Base case: if k is 0 or n is 0, return 1
    if k == 0 or n == 0:
        return 1
    # Recursive case: multiply n! by (n-k)!
    return n * permutation_coefficient(n-1, k-1)
```
